  // Rotated sessions (gh-1077) keep older records in `.part-NN`
  // segments: scan the whole chain in order or registry snapshots
  // flushed before the last rotation become invisible to subagent
  // adoption (#488), memory refresh and ttsr. Dedupe by record id:
  // between a failed rotation seed and the next open the archived
  // part and the restored primary hold the SAME records — the open
  // path dedupes (seenRecordIds), the raw scan must too (round 5).
  //
  // Tail cap (the goal_builder 2.7GB incident): the windowed storage
  // never rotates, so a marathon session's PRIMARY grows unbounded
  // (measured 2.7GB against the 80MB rotate / 95MB hard-cap design),
  // and a from-offset-0 scan of it sat on the resume boot path for
  // 10+ seconds (orphan-report seed) and churned post-boot
  // (steering, obligations). Every consumer today is a TAIL consumer
  // (`records.last`, or pending-vs-consumed steering where a pair
  // entirely beyond the cap cancels itself), so the default bounds
  // each FILE to the tail region a properly rotated primary promised
  // ([kSessionSegmentHardCapBytes]); rotated `.part-NN` files are
  // smaller than that and scan in full. Deep-history callers pass
  // `tailCapBytes: null`.
  final cap = tailCapBytes ?? kSessionSegmentHardCapBytes;
  final paths = await listSessionSegmentPaths(_fs, metadata.path);
  final scanned = lastSegmentOnly ? paths.sublist(paths.length - 1) : paths;
  final records = <CustomRecord>[];
  final seen = <String>{};
  for (final path in scanned) {
    for (final record in await _readCustomRecordsInFile(path, types, cap)) {
      if (seen.add(record.id)) records.add(record);
    }
  }
  return records;
}

/// Single-file scan behind [readCustomRecordsOfType]; see its
/// docstring. Returns [] for a missing/unreadable file.
Future<List<CustomRecord>> _readCustomRecordsInFile(
  String path,
  Set<String> types,
  int? tailCapBytes,
) async {
  final fs = _fs;
  if (fs case final RangedReadFileSystem ranged) {
    return _readCustomRecordsStreamed(fs, ranged, path, types, tailCapBytes);
  }
  // Non-ranged filesystems (in-memory hosts) carry small sessions;
  // the cap degrades to no-op there rather than approximating byte
  // offsets over decoded lines.
  final read = await fs.readTextLines(path);
  if (read.isErr) return const [];
  final records = <CustomRecord>[];
  for (final line in read.valueOrNull ?? const <String>[]) {
    if (!types.any(line.contains)) continue;
    _decodeCustomRecord(line, types, records);
  }
  return records;
}

/// Full-archive search over [metadata]'s session chain (issue #1380
/// A2): the streamed, bounded scan in `session_search.dart` run against
/// this repo's file system — the repo exists so hosts never need the
/// private fs to reach the file.
Future<SessionSearchOutcome> searchArchive(
  SessionMetadata metadata,
  SessionSearchQuery query,
) => searchSessionFile(_fs, metadata.path, query);

/// Scan block size for [_readCustomRecordsStreamed]; tests shrink it to
/// exercise the block-seam logic (lines and gates spanning blocks).
@visibleForTesting
static var debugCustomRecordScanBlockBytes = 8 << 20;

/// Blocked scan behind [readCustomRecordsOfType]; see its docstring.
///
/// Per-block pipeline: `latin1.decode` (byte→char identity memcpy —
/// measured 3x cheaper than validating `utf8.decode`, 322ms vs 941ms
/// on a 434MB marathon file), then gate-hit scanning via native
/// `String.indexOf` — hits are as rare as the records themselves (14
/// on that file), so full lines materialize only around an actual hit
/// instead of substring-copying every line for a per-line `contains`.
/// latin1 is byte-exact for the ASCII gate and line feeds, and
/// `latin1.encode` restores a matching line's original bytes for the
/// real `utf8.decode` + `jsonDecode` — semantics identical to the
/// whole-file path.
Future<List<CustomRecord>> _readCustomRecordsStreamed(
  FileSystem fs,
  RangedReadFileSystem ranged,
  String path,
  Set<String> types,
  int? tailCapBytes,
) async {
  final blockBytes = debugCustomRecordScanBlockBytes;
  final info = await fs.fileInfo(path);
  if (info.isErr) return const [];
  if (info.valueOrNull!.kind != FileKind.file) return const [];
  final size = info.valueOrNull!.size;
  final scanner = _CustomRecordBlockScanner(types);
  // Start inside the tail region: a line torn at the boundary simply
  // fails the field-shaped gate (or jsonDecode) and is skipped — the
  // cap trades deep history, never correctness.
  var offset = tailCapBytes == null
      ? 0
      : math.max(0, size - tailCapBytes);
  while (offset < size) {
    final end = (offset + blockBytes).clamp(0, size);
    final read = await ranged.readRange(path, offset, end);
    if (read.isErr) return const [];
    final block = read.valueOrNull!;
    if (block.isEmpty) break;
    offset = end;
    scanner.scanBlock(json_conv.latin1.decode(block));
  }
  return scanner.finish();
}

/// Decodes one gated line into [records]; malformed JSON (crash-torn
/// tail) and non-matching parsed records are skipped.
static void _decodeCustomRecord(
  String line,
  Set<String> types,
  List<CustomRecord> records,
) {
  final Object? json;
  try {
    json = json_conv.jsonDecode(line);
  } on Object {
    return; // torn tail line from a crash — skip.
  }
  if (json is! Map) return;
  final record = SessionRecord.fromJson(json.cast<String, dynamic>());
  if (record is CustomRecord && types.contains(record.customType)) {
    records.add(record);
  }
}

