        final sink = FileStreamTraceSink(
          file,
          flushInterval: const Duration(hours: 1),
        );
        StreamTrace.start(sink);

        StreamTrace.mark(StreamTraceMark.net, '+8B');
        StreamTrace.mark(StreamTraceMark.emit, 'text +2');

        // Nothing hit the disk per line: the marks sit in the buffer
        // (the interval is an hour away, so only flush() can land them).
        expect(
