    final first = _parse(sink.lines[0]);
    expect(first.mark, 'net');
    expect(first.seq, 1);
    expect(first.detail, '+512B');
    final second = _parse(sink.lines[1]);
    expect(second.mark, 'emit');
    expect(second.seq, 2);
