/// A line-buffered appending sink over [file]: truncates whatever a
/// previous run left, then BUFFERS incoming lines and flushes them to
/// disk as one appbed+flushed write every [flushInterval] (or as soon
/// as the buffer passes [kFlushThresholdBytes], or explicitly via
/// [flush]) — a per-chunk `flush: true` write sat on the hottest path in
/// the provider pipeline (up to three sync writes per streamed delta)
/// and perturbed the very latency the trace measures. The pending timer
/// keeps the process alive at most one interval past the last mark.
/// Diagnostics contract: an IO failure degrades to silence, never throws
/// into the caller.
final class FileStreamTraceSink implements StreamTraceSink {
 FileStreamTraceSink(this._file, {this.flushInterval = const Duration(milliseconds: 250)}) {
   try {
     _file.writeAsStringSync('', flush: true);
   } catch (_) {
     // A broken trace path never breaks the host.
   }
 }

 /// How long lines may sit in the buffer before one batched
 /// append+flush write lands them.
 final Duration flushInterval;

 /// Flush threshold: a buffer this big flushes immediately instead of
 /// waiting for the timer (bounds memory on a burst).
 static const _flushThresholdBytes = 32 << 10;

 final File _file;
 final StringBuffer _pending = StringBuffer();
 Timer? _flushTimer;

 @override
 void writeLine(String line) {
   try {
     _pending
       ..write(DateTime.now().toIso8601String())
       ..write(' ')
       ..write(line)
       ..writeln();
     if (_pending.length >= _flushThresholdBytes) {
       flush();
     } else {
       _flushTimer ??= Timer(flushInterval, flush);
     }
   } catch (_) {
     // A broken trace path never breaks the host.
   }
 }

 /// Writes the buffered lines to disk now (one appended+flushed write).
 /// Safe to call repeatedly; the timer rearms on the next line.
 void flush() {
   _flushTimer?.cancel();
   _flushTimer = null;
   if (_pending.isEmpty) return;
   final batch = _pending.toString();
   _pending.clear();
   try {
     _file.writeAsStringSync(batch, mode: FileMode.append, flush: true);
   } catch (_) {
     // A broken trace path never breaks the host.
   }
 }
``

