```dart
final class FileStreamTraceSink implements StreamTraceSink {
 FileStreamTraceSink(
   this._file, {
   this.flushInterval = const Duration(milliseconds: 250),
 }) {
   try {
     _file.writeAsStringSync('', flush: true);
   } catch (_) {
     // A broken trace path never breaks the host.
   }
 }

 /// How long a buffered line may wait before the batched write lands
 /// it. One-shot timer, rearmed per buffered line: the process lingers
 /// at most this long past the last mark (the trace must not hold the
 /// host's exit open any longer).
 final Duration flushInterval;

 /// Buffered lines flush immediately past this size — bounds the
 /// memory a burst can pin and keeps any single write bounded.
 static const _flushThresholdBytes = 32 << 10;

 final File _file;
 final StringBuffer _pending = StringBuffer();
 Timer? _flushTimer;

 @override
 void writeLine(String line) {
   try {
     _pending
       ..write(DateTime.now().toIso8601String())
       ..write(' ')
       ..write(line)
       ..writeln();
     if (_pending.length >= _flushThresholdBytes) {
       flush();
     } else {
       // One pending timer at a time; rearm stops when the buffer
       // drains.
       _flushTimer ??= Timer(flushInterval, flush);
     }
   } catch (_) {
     // A broken trace path never breaks the host.
   }
 }

 /// Lands the buffered lines now — one appended+flushed write — and
 /// cancels the pending interval flush. Safe to call repeatedly; the
 /// timer rearms on the next buffered line.
 void flush() {
   _flushTimer?.cancel();
   _flushTimer = null;
   if (_pending.isEmpty) return;
   final batch = _pending.toString();
   _pending.clear();
   try {
     _file.writeAsStringSync(batch, mode: FileMode.append, flush: true);
   } catch (_) {
     // A broken trace path never breaks the host.
   }
 }
