{"content":"/// The dart:io half of StreamTrace — the file sink, the log-path
/// resolver, and the env-gated installer. The pure contract (marks,
/// line format, active-trace lifecycle) lives in `stream_trace.dart`
/// (barrel-exported); this file is reachable exclusively through
/// `lib/io.dart`, same pattern as `stall_sentinel_io.dart`.
library;

import 'dart:async';
import 'dart:io';

import 'stream_trace.dart';

/// A line-BUFFERED appending sink over [file]: truncates whatever a
/// previous run left, then buffers incoming lines and lands them as one
/// appended+flushed batch every [flushInterval] (or immediately once
/// the buffer passes 32KB, or explicitly via [flush]). The batched
/// write replaces the original per-line `flush: true` append: the marks
/// sit on the hottest path in the provider pipeline (up to three marks
/// per streamed delta), and a synchronous flush per chunk stalled the
/// event loop by milliseconds and perturbed the very latency the trace
/// measures. The pending interval timer outlives the last mark by at
/// most one interval — the trace never holds the host's exit open
/// longer than that. Diagnostics contract: an IO failure degrades to
/// silence, never throws into the caller.
final class FileStreamTraceSink implements StreamTraceSink {
  /// Creates the sink, truncating [file] for a fresh trace (one armed
  /// run replaces the previous run's trace).
  FileStreamTraceSink(
    this._file, {
    this.flushInterval = const Duration(milliseconds: 250),
  }) {
    try {
      _file.writeAsStringSync('', flush: true);
    } catch (_) {
      // A broken trace path never breaks the host.
    }
  }

  /// How long a buffered line may wait before the batched write lands
  /// it. A one-shot timer rearmed per buffered line, so the process
  /// lingers at most this long past the last mark.
  final Duration flushInterval;

  /// A buffer this big flushes inline instead of waiting for the
  /// interval — bounds the memory a burst can pin and keeps any single
  /// write bounded.
  static const _flushThresholdBytes = 32 << 10;

  final File _file;
  final StringBuffer _pending = StringBuffer();
  Timer? _flushTimer;

  @override
  void writeLine(String line) {
    try {
      _pending
        ..write(DateTime.now().toIso8601String())
        ..write(' ')
        ..write(line)
        ..writeln();
      if (_pending.length >= _flushThresholdBytes) {
        flush();
      } else {
        // One pending timer at a time; it stops rearming once the
        // buffer drains.
        _flushTimer ??= Timer(flushInterval, flush);
      }
    } catch (_) {
      // A broken trace path never breaks the host.
    }
  }

  /// Lands the buffered lines now — one appended+flushed write — and
  /// cancels the pending interval flush. Safe to call repeatedly; the
  /// timer rearms on the next buffered line.
  void flush() {
    _flushTimer?.cancel();
    _flushTimer = null;
    if (_pending.isEmpty) return;
    final batch = _pending.toString();
    _pending.clear();
    try {
      _file.writeAsStringSync(batch, mode: FileMode.append, flush: true);
    } catch (_) {
      // A broken trace path never breaks the host.
    }
  }
}

/// Resolves the StreamTrace log path for the running host:
/// `$HOME/.fah/logs/stream-trace.log`, falling back to `USERPROFILE`
/// for Windows hosts (`HOME` is typically unset there — without the
/// fallback `FA_STREAM_TRACE=1` silently armed nothing on Windows).
/// Returns null when neither is set: the knob cannot arm, and the
/// caller skips the install.
String? streamTraceLogPath({
  required String? Function(String key) envLookup,
}) {
  final home = envLookup('HOME') ?? envLookup('USERPROFILE');
  if (home == null || home.isEmpty) return null;
  return '$home/.fah/logs/stream-trace.log';
}

/// Starts a [StreamTrace] into [file] when the env knob is on:
/// `FA_STREAM_TRACE=1` (exactly `1`; any other value or an unset key
/// keeps the trace off). Returns the started trace, or null when the
/// knob is off. Arming TRUNCATES [file] — the new run's trace replaces
/// the previous run's ([FileStreamTraceSink] truncates at
/// construction), so collect traces per run. [envLookup] is a test
/// seam; real hosts pass `(key) => Platform.environment[key]`.
StreamTrace? maybeStartStreamTrace(
  File file, {
  required String? Function(String key) envLookup,
  Duration flushInterval = const Duration(milliseconds: 250),
}) {
  if (envLookup('FA_STREAM_TRACE') != '1') return null;
  return StreamTrace.start(
    FileStreamTraceSink(file, flushInterval: flushInterval),
  );
}
