          customType: 'orphan_report',
          data: {'n': 'new'},
        ))}\n',
      );
      await raw.flush();
      await raw.close();

      // The fixture must genuinely cross the cap, or this test proves
      // nothing (the vacuous-70KB-fixture trap the review called out).
