      // writes — deliberately bypassing the storage append path, whose
      // hard-cap handling would drop the oldest records the moment the
      // active segment crosses the cap. Reading such a giant back is
      // exactly what the `tailCapBytes: null` contract is for, so the
      // fixture must be the real thing.
      const chunkBytes = 1 << 20; // 1MB filler lines
      final filler = '{"filler":"${'x' * (chunkBytes - 14)}"}\n';
      final raw = io.File(metadata.path).openWrite(mode: io.FileMode.append);
      for (var i = 0; i < 100; i++) {
        raw.write(filler);
      }
      raw.write(
        '${jsonEncode(const CustomRecord(
          id: 'raw-new',
          timestamp: '2026-10-20T19:00:00.000Z',
          customType: 'orphan_report',
          data: {'n': 'new'},
        ))}\n',
      );
      await raw.flush();
      await raw.close();

      // The fixture must genuinely cross the cap, or this test proves
      // nothing (the vacuous-70KB-fixture trap the review called out).
      expect(
        await io.File(metadata.path).length(),
        greaterThan(kSessionSegmentHardCapBytes),
      );

      // DEFAULT (no argument): the tail region a properly rotated
      // primary promises — the deep 'old' record is beyond the cap.
      final tail = await repo.readCustomRecordsOfType(metadata, {
        'orphan_report',
      });
      expect(tail.map((r) => (r.data as Map)['n']), ['new']);

      // Explicit unbounded: null must differ from the default — the
      // whole file from offset 0, both records.
      final all = await repo.readCustomRecordsOfType(
        metadata,
        {'orphan_report'},
        tailCapBytes: null,
      );
      expect(all.map((r) => (r.data as Map)['n']), ['old', 'new']);
    },
    timeout: const Timeout(Duration(seconds: 120)),
  );"}

