{"path":"test/providers/stream_trace_io_test.dart","content":"// StreamTrace io half: the file sink and the env-gated installer —
// same "diagnostics must never break the host" contract as the fa.log
// telemetry sink (truncates at install, line-buffered with a short
// interval flush, silent on any IO failure).
import 'dart:io';

import 'package:flutter_agent_harness/src/providers/stream_trace.dart';
import 'package:flutter_agent_harness/src/providers/stream_trace_io.dart';
import 'package:test/test.dart';

void main() {
  group('FileStreamTraceSink', () {
    late Directory dir;
    late File file;

    setUp(() {
      dir = Directory.systemTemp.createTempSync('stream-trace-test');
      file = File('${dir.path}/trace.log');
    });

    tearDown(() {
      StreamTrace.stop();
      if (dir.existsSync()) dir.deleteSync(recursive: true);
    });

    test('truncates previous content at construction', () {
      file.writeAsStringSync('stale\n');
      FileStreamTraceSink(file, flushInterval: const Duration(hours: 1));
      expect(file.readAsStringSync(), isEmpty);
    });

    test(
      'writeLine buffers — no per-line synchronous write on the hot '
      'stream path; flush() lands the batch',
      () {
        final sink = FileStreamTraceSink(
          file,
          flushInterval: const Duration(hours: 1),
        );
        StreamTrace.start(sink);

        StreamTrace.mark(StreamTraceMark.net, '+8B');
        StreamTrace.mark(StreamTraceMark.emit, 'text +2');

        // Nothing hit the disk per line: the marks sit in the buffer
        // (the interval is an hour away, so only flush() can land them).
        expect(
          file.readAsStringSync(),
          isEmpty,
          reason: 'per-line sync writes perturb the very latency the '
              'trace measures',
        );

        sink.flush();

        final lines = file.readAsLinesSync();
        expect(lines, hasLength(2));
        // Wall-clock iso prefix + the pure body, one line each.
        expect(lines[0], contains(RegExp(r'^\d{4}-\d{2}-\d{2}T')));
        expect(lines[0], contains('net'));
        expect(lines[1], contains('emit'));
        expect(file.readAsStringSync(), isNot(contains('stale')));
      },
    );

    test('buffered lines land on the flush interval without an explicit flush', () async {
      final sink = FileStreamTraceSink(
        file,
        flushInterval: const Duration(milliseconds: 20),
      );
      StreamTrace.start(sink);

      StreamTrace.mark(StreamTraceMark.net, '+8B');
      expect(file.readAsStringSync(), isEmpty);
      await Future<void>.delayed(const Duration(milliseconds: 80));

      expect(file.readAsStringSync(), contains('net'));
      sink.flush();
    });

    test('a buffer past the flush threshold lands immediately, no timer wait', () {
      final sink = FileStreamTraceSink(
        file,
        flushInterval: const Duration(hours: 1),
      );
      StreamTrace.start(sink);

      // ~40KB of marks crosses the 32KB threshold: flushed inline
      // although the interval flush is an hour away.
      for (var i = 0; i < 40; i++) {
        StreamTrace.mark(StreamTraceMark.net, '+${'x' * 1000}B');
      }
      expect(file.readAsStringSync(), contains('net'));
      sink.flush();
    });

    test('a write failure degrades to silence, never throws', () {
      final sink = FileStreamTraceSink(file);
      StreamTrace.start(sink);
      dir.deleteSync(recursive: true);
      expect(
        () {
          StreamTrace.mark(StreamTraceMark.net, '+1B');
          sink.flush(); // the write itself fails — caught, silent.
        },
        returnsNormally,
      );
    });
  });

  group('maybeStartStreamTrace', () {
    late Directory dir;

    setUp(() {
      dir = Directory.systemTemp.createTempSync('stream-trace-env-test');
    });

    tearDown(() {
      StreamTrace.stop();
      if (dir.existsSync()) dir.deleteSync(recursive: true);
    });

    test('starts a trace only when the env value is 1', () async {
      final file = File('${dir.path}/on.log');
      final trace = maybeStartStreamTrace(
        file,
        envLookup: (key) => key == 'FA_STREAM_TRACE' ? '1' : null,
        flushInterval: const Duration(milliseconds: 10),
      );
      expect(trace, isNotNull);
      expect(StreamTrace.active, same(trace));
      StreamTrace.mark(StreamTraceMark.net, '+1B');
      await Future<void>.delayed(const Duration(milliseconds: 50));
      expect(file.readAsStringSync(), contains('net'));
    });

    test('any other value (or unset) keeps the trace off', () {
      for (final value in <String?>[null, '', '0', 'true', '2']) {
        final trace = maybeStartStreamTrace(
          File('${dir.path}/off-$value.log'),
          envLookup: (key) => key == 'FA_STREAM_TRACE' ? value : null,
        );
        expect(trace, isNull, reason: 'FA_STREAM_TRACE=$value');
        expect(StreamTrace.active, isNull);
      }
    });
  });

  group('streamTraceLogPath', () {
    test('resolves the log under HOME', () {
      expect(
        streamTraceLogPath(
          envLookup: (key) => key == 'HOME' ? '/home/u' : null,
