      // primary promises — the deep 'old' record is beyond the cap.
      final tail = await repo.readCustomRecordsOfType(metadata, {
        'orphan_report',
      });
      expect(tail.map((r) => (r.data as Map)['n']), ['new']);

      // Explicit unbounded: null must differ from the default — the
      // whole file from offset 0, both records.
      final all = await repo.readCustomRecordsOfType(
        metadata,
        {'orphan_report'},
        tailCapBytes: null,
      );
      expect(all.map((r) => (r.data as Map)['n']), ['old', 'new']);
    },
    timeout: const Timeout(Duration(seconds: 120)),
  );"}

