index 04ea6b5149..a0690accb6 100644
--- a/lib/src/session/session_repo.dart
+++ b/lib/src/session/session_repo.dart
@@ -817,7 +817,7 @@ final class JsonlSessionRepo implements SessionRepo {
     SessionMetadata metadata,
     Set<String> types, {
     bool lastSegmentOnly = false,
-    int? tailCapBytes,
+    int? tailCapBytes = kSessionSegmentHardCapBytes, // null = unbounded
   }) async {
     // Rotated sessions (gh-1077) keep older records in `.part-NN`
     // segments: scan the whole chain in order or registry snapshots
@@ -837,15 +837,22 @@ final class JsonlSessionRepo implements SessionRepo {
     // entirely beyond the cap cancels itself), so the default bounds
     // each FILE to the tail region a properly rotated primary promised
     // ([kSessionSegmentHardCapBytes]); rotated `.part-NN` files are
-    // smaller than that and scan in full. Deep-history callers pass
-    // `tailCapBytes: null`.
-    final cap = tailCapBytes ?? kSessionSegmentHardCapBytes;
+    // smaller than that and scan in full. `null` is the real unbounded
+    // opt-out (the parameter DEFAULTS to the cap instead of coalescing
+    // — `?? kSessionSegmentHardCapBytes` made null identical to
+    // omitting it, so the documented deep-history opt-out silently
+    // didn't exist): a deep-history caller passing `tailCapBytes: null`
+    // scans every file in full from offset 0.
     final paths = await listSessionSegmentPaths(_fs, metadata.path);
     final scanned = lastSegmentOnly ? paths.sublist(paths.length - 1) : paths;
     final records = <CustomRecord>[];
     final seen = <String>{};
     for (final path in scanned) {
-      for (final record in await _readCustomRecordsInFile(path, types, cap)) {
+      for (final record in await _readCustomRecordsInFile(
+        path,
+        types,
+        tailCapBytes,
+      )) {
         if (seen.add(record.id)) records.add(record);
       }
     }

